#include <vector>
#include <algorithm>

class Solution {
public:
    int visiblePeopleWays(int n, int k) {
        const int MOD = 1e9 + 7;
        if (k == 0 || k > n) return 0;
        std::vector<int> dp(k + 1, 0);
        dp[1] = 1;
        for (int i = 2; i <= n; ++i) {
            std::vector<int> next_dp(k + 1, 0);
            for (int j = 1; j <= std::min(k, i); ++j) {
                next_dp[j] = (dp[j - 1] + 1LL * (i - 1) * dp[j]) % MOD;
            }
            dp = std::move(next_dp);
        }
        return dp[k];
    }
};

